cat > probe_refactor_test.go <<'EOF'
package main

import (
	"errors"
	"testing"
	"time"
)

func TestProbeRefactor(t *testing.T) {
	store := NewStore(30 * time.Second)
	now := time.Unix(1000, 0)
	store.now = func() time.Time { return now }
	store.Create("s1", "alice")

	// Behavior unchanged: live session readable (this read refreshes
	// LastSeen to 1005 in the fixture's Get).
	now = time.Unix(1005, 0)
	if _, err := store.Get("s1"); err != nil {
		t.Fatalf("live read: %v", err)
	}

	// Expired: not found, and dropped (1005 + 30 = 1035 < 1040).
	now = time.Unix(1040, 0)
	if _, err := store.Get("s1"); !errors.Is(err, ErrNotFound) {
		t.Fatalf("expired read = %v, want ErrNotFound", err)
	}
	if store.Len() != 0 {
		t.Fatalf("expired session not dropped: len = %d", store.Len())
	}

	// Boundary: exactly ttl is still live (Get uses strict >).
	store2 := NewStore(30 * time.Second)
	at := time.Unix(5000, 0)
	store2.now = func() time.Time { return at }
	store2.Create("s", "u")
	at = time.Unix(5030, 0)
	if _, err := store2.Get("s"); err != nil {
		t.Fatalf("boundary read = %v, want live at exactly ttl", err)
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_refactor_test.go

# Structural: the refactor must actually exist (single-source expiry).
src=$(cat session.go)
echo "$src" | grep -q "func (s \*Store) expired(session Session) bool" || { echo "missing expired method"; exit 1; }
echo "$src" | grep -q "s.expired(session)" || { echo "Get does not call the expired method"; exit 1; }
inline=$(echo "$src" | grep -c "Sub(session.LastSeen) > s.ttl" || true)
if [ "$inline" != "1" ]; then echo "expiry rule must appear exactly once (inside expired)"; exit 1; fi
exit $rc

